     final enrollment = Enrollment(
         id: _id('ins_'),
         activityId: activityId,
         participantId: user.id,
         status: semVaga ? 'em_espera' : 'confirmada',
         sequenceNumber: ++_enrollmentSequence,
         createdAt: clock);
